import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Gregor Kobel', position: 'GK', age: 28, club: 'Borussia Dortmund', bio: {"es":"Tras una larga espera, Kobel se ha convertido por fin en el portero titular de Suiza tras la retirada de Yann Sommer en otoño de 2024. Con la selección nacional todavía no ha conseguido repetir su excelente forma en el Borussia Dortmund y no fue hasta su decimotercer partido internacional que el portero nacido en Zúrich consiguió mantener su portería a cero por primera vez. Kobel puede ser el jugador más valioso del equipo suizo, según Transfermarkt, y es un líder importante en el equipo, pero no le gusta ser el centro de atención y rara vez aparece en los titulares. Cuando era adolescente, Kobel tenía tantos talentos que aspiraba a hacer carrera en el tenis, el snowboard o el hockey sobre hielo, además del fútbol.","en":"After a long wait, Kobel has finally become Switzerland’s first-choice goalkeeper following Yann Sommer’s retirement in the autumn of 2024. For the national team he has not yet quite managed to replicate his outstanding form at Borussia Dortmund and it was not until his 13th international that the Zurich-born keeper managed to keep his first clean sheet. Kobel may be the most valuable player in the Swiss squad – according to Transfermarkt – and is an important leader in the squad but he doesn’t like the spotlight and rarely finds himself creating headlines. As a teenager, Kobel was so multi-talented he aspired to a career in tennis, snowboarding or ice hockey as well as football."}, special: "No 1 goalkeeper" },
  { number: 12, name: 'Yvon Mvogo', position: 'GK', age: 32, club: 'Lorient', bio: {"es":"El portero camerunés es el número 2 perfecto. Se adapta bien al equipo, acepta su papel y está ahí cuando se le necesita. \"Siempre ha estado de buen humor, con una sonrisa en la cara, un verdadero favorito de los aficionados\", dijo una vez su entrenador en el Young Boys, Uli Forte. Ha impresionado en prácticamente todas sus 12 apariciones internacionales, manteniendo seis porterías a cero. Sin embargo, su carrera en el club no siempre ha sido fácil. En 2017, cuando era considerado uno de los porteros más talentosos del continente, dejó el YB, pero no logró consolidarse en el RB Leipzig. A través de Eindhoven, acabó en Lorient, donde rechazó ofertas de Parma y Celtic antes de descender el verano pasado. Parecía que iba a abandonar el club francés pero acabó dimitiendo. Cuando era niño, el servicio religioso era obligatorio para él los domingos. “No me apetecía, porque siempre era mi único día libre”, dice con una sonrisa. “Pero mi madre me dijo que es importante agradecer a Dios”.","en":"The Cameroon-born goalkeeper is the perfect No 2. He fits in well with the team, accepts his role and is there when needed. \"He has always been in a good mood, with a smile on his face – a real fan favourite,\" his coach at Young Boys, Uli Forte, once said. He has impressed in virtually all of his 12 international appearances, keeping six clean sheets. His club career has not always followed a smooth path, however. In 2017, when he was regarded as one of the most talented goalkeepers on the continent, he left YB but failed to establish himself at RB Leipzig. Via Eindhoven, he ended up at Lorient where he turned down offers from Parma and Celtic before getting relegated last summer. It looked like he was going to leave the French club but ended up resigning. As a child, church service was compulsory for him on Sundays. “I didn’t fancy it, as it was always my only day off,” he says with a smile. “But my mother told me me that it’s important to thank God.”"} },
  { number: 21, name: 'Marvin Keller', position: 'GK', age: 24, club: 'Young Boys', bio: {"es":"Keller es “un calcetín genial”, según uno de sus excompañeros del Young Boys, Fabian Rieder, “como persona y como portero”. Eso es suizo-alemán por estar tranquilo y sereno. Aunque puede ser ruidoso en el campo. “Tal vez sea porque es de Zúrich”, sugiere Sandro Lauper, actual compañero de equipo. Nacido en Londres cuando su padre trabajaba allí, Keller creció y pasó por los equipos juveniles del Grasshopper en Suiza. Se le considera uno de los porteros más prometedores de Suiza y, en los últimos dos años, ha luchado por ascender desde la segunda división para sustituir a David von Ballmoos en el Young Boys, campeón en serie. Es posible que esté en movimiento en el verano y ha dicho: \"Quiero jugar en una liga entre los cinco primeros\".  Jugó en la Eurocopa sub-21, pero en el momento de escribir este artículo aún no ha hecho su debut internacional absoluto.","en":"Keller is ‘a cool sock’ according to one of his former Young Boys teammates, Fabian Rieder, “as a person and as a goalkeeper”. That is Swiss-German for being calm and collected. He can be loud on the pitch though. “Maybe that is because he is from Zurich,” a current teammate, Sandro Lauper, suggests. Born in London when his father was working there, Keller grew up and came through the youth teams at Grasshopper in Switzerland. He is regarded as one of Switzerland’s most promising goalkeeping talents and, in the past two years, has fought his way up from the second division to replace David von Ballmoos at serial champions Young Boys. He may well be on the move in the summer and has said: “I want to play in a top-five league.”  Played at the Under-21 Euros but has yet to make his senior international debut at the time of writing."} },
  // Defensores
  { number: 2, name: 'Miro Muheim', position: 'DF', age: 28, club: 'Hamburg', bio: {"es":"Se mudó de Zúrich al Chelsea cuando tenía 16 años y, aunque no llegó hasta el primer equipo, guarda fantásticos recuerdos de su estancia en Londres. \"Te vuelves más maduro mudándote al extranjero por tu cuenta y la configuración fue fantástica. Recuerdo que de repente Eden Hazard apareció en el vestuario mientras jugaba para la sub-23 mientras volvía a estar en forma. Fue muy agradable y relajado. Y qué jugador. Demostró de inmediato lo que se puede hacer con una pelota: simplemente sensacional\". Regresó a Suiza y St Gallen en 2018 y logró un gran avance a pesar de haber sufrido una lesión del ligamento anterior cruzado desde el principio. Tres años más tarde fichó por el Hamburgo y disputó su primera internacionalidad con Suiza como jugador de la 2. Bundesliga antes de ascender a la máxima categoría. Ahora es parte del grupo de liderazgo de HSV.","en":"Moved from Zurich to Chelsea as a 16-year-old and while he did not make it all the way to the first team he has some tremendous memories from his time in London. “You become more mature by moving abroad on your own and the set-up was fantastic. I remember Eden Hazard suddenly being in the changing room as he was playing for the Under-23s while returning to fitness. He was so nice and relaxed. And what a player. He showed straight away what you can do with a ball: simply sensational.” Returned to Switzerland and St Gallen in 2018 and made the breakthrough despite having suffered an ACL injury early on. Joined Hamburg three years later and won his first Switzerland cap as a 2. Bundesliga player before being promoted to the top flight. Is now part of the leadership group at HSV."} },
  { number: 3, name: 'Silvan Widmer', position: 'DF', age: 33, club: 'Mainz', bio: {"es":"De vuelta en forma después de una etapa difícil para el país y el club, el lateral ofensivo recuperó su puesto titular para ambos durante la temporada 2025-26. \"Por supuesto, la temporada pasada fue decepcionante para mí\", dijo. \"Pero no soy el tipo de persona que alberga frustración. Nunca tuve que esforzarme para seguir adelante; siempre disfruté ser parte del equipo y, como resultado, también fui un modelo a seguir para otros que estaban pasando por momentos difíciles\". Es un jugador muy fiable, pero rivales de gran calibre pueden causarle problemas, como fue el caso en la derrota por 4-3 contra Alemania en marzo. Capitán del Mainz, no teme hablar de temas delicados y dijo que si tuviera que ser capitán durante el Mundial de Qatar definitivamente llevaría el brazalete arcoíris y también ha dicho que nunca jugaría en Arabia Saudita. Mientras estaba lesionado en Mainz en 2023, dijo: “Puedo pasar más tiempo en casa y allí hago lo que sea necesario, ya sea llevar paquetes a la oficina de correos o ayudar a mi esposa Céline con su propia empresa”.","en":"Back in form after a difficult spell for country and club, the attacking full-back regained his starting place for both during the 2025-26 season. “Of course, last season was disappointing for me,” he said. “But I’m not the sort of person who harbours frustration. I never had to force myself to get going; I always enjoyed being part of the team and, as a result, was also a role model for others who were going through a difficult time.” He is a very reliable player but opponents of the highest calibre can cause him problems, as was the case in the 4-3 defeat against Germany in March. A captain at Mainz, he is not afraid to discuss sensitive topics and said that if he had to step in as captain during the World Cup in Qatar he would definitely wear the rainbow armband and he has also said he would never play in Saudi Arabia. While injured at Mainz in 2023, he said: “I get to spend more time at home and there I do whatever is needed, whether that is taking packages to the post office or helping my wife Céline with her own company.”"} },
  { number: 4, name: 'Nico Elvedi', position: 'DF', age: 29, club: 'Borussia Mönchengladbach', bio: {"es":"El jugador nacido en Zúrich y con raíces en los Grisones se mudó de Zúrich a Mönchengladbach cuando era un adolescente en 2015, y todavía está allí. Se ha hablado de un movimiento, pero nunca se materializó y ahora, de hecho, es el jugador con más apariciones de todos los tiempos del club en la Bundesliga.  Apodado 'Eisvogel' (Martín pescador) en Alemania después de un debut tranquilo y sereno contra el Bayern de Múnich de todos los equipos. El hermano gemelo de Nico, Jan, también es futbolista profesional y recientemente estuvo cedido por el Kaiserslautern al Greuther Fürth. Jan elogia a su hermano, aunque cree que puede ser \"demasiado amable\" en el campo. \"Nico es un todoterreno y prácticamente no tiene debilidades\", afirma Jan. \"Pero quizá podría ser un poco más agresivo y utilizar un poco más los codos\". El mayor deseo de los hermanos: jugar uno contra el otro algún día. Elvedi ha regresado con fuerza a la selección nacional después de un año difícil en el que perdió su lugar en el once inicial para la Eurocopa 2024. Estuvo entre los mejores jugadores de Suiza en las eliminatorias para el Mundial.","en":"The Zurich-born player with roots in Graubünden moved from Zurich to Mönchengladbach as a teenager in 2015 – and is still there. There have been talks of a move, but it never materialised and he is now, in fact, the club’s all-time leading appearance-holder in the Bundesliga.  Nicknamed ‘Eisvogel’ (Kingfisher) In Germany after a cool and composed debut against Bayern Munich of all teams. Nico’s twin brother Jan is also a professional footballer and was most recently on loan from Kaiserslautern to Greuther Fürth. Jan is full of praise for his brother, although thinks he may be a little bit “too nice” on the pitch. “Nico is an all-rounder and has practically no weaknesses,” says Jan. “But perhaps he could be a bit more aggressive and use his elbows a bit more.” The brothers’ greatest wish: to play against each other one day. Elvedi has made a strong comeback for the national team after a difficult year when he lost his place in the starting line-up for Euro 2024. He was among the best Switzerland players in the World Cup qualifiers."}, special: "'The Kinfisher'" },
  { number: 5, name: 'Manuel Akanji', position: 'DF', age: 30, club: 'Inter', bio: {"es":"Se ha convertido en un defensa de talla mundial en el Manchester City y el Inter y, junto con Granit Xhaka, en un líder indiscutible de la selección nacional. Su padre es de Nigeria y su segundo nombre “Obafemi” significa “amado del rey”, por lo que tenía una corona tatuada en su antebrazo izquierdo. Otro tatuaje, “Demuéstrales que están equivocados”, se hizo después de las dudas de que llegaría hasta el final mientras jugaba con las categorías inferiores del FC Winterthur. Incluso superó una lesión del ligamento anterior cruzado en Basilea para continuar su ascenso a la cima. A principios de 2018, con sólo 22 años, se mudó al Borussia Dortmund por £23,5 millones y cuatro años después al Manchester City, donde ganó el triplete en 2023. Akanji también es bueno con los números; Una vez, en un programa de televisión, prometió a toda Suiza con sus habilidades de cálculo mental. El vídeo se volvió viral.","en":"Has developed into a world-class defender at Manchester City and Inter and, together with Granit Xhaka, an undisputed leader for the national team. His father is from Nigeria and his middle name “Obafemi” means “beloved of the king”, which is why he had a crown tattooed on his left forearm. Another tattoo – “Prove them wrong” – was inked after doubts that he would make it all the way while with the FC Winterthur youth teams. He even overcame an ACL injury at Basel to continue his rise to the top. At the start of 2018, aged just 22, he moved to Borussia Dortmund for £23.5m and four years later to Manchester City, where he won the treble in 2023. Akanji is also good with numbers; he once vowed the whole of Switzerland with his mental arithmetic skills on a TV show. The video went viral."}, special: "Defensive leader" },
  { number: 13, name: 'Ricardo Rodriguez', position: 'DF', age: 33, club: 'Real Betis', bio: {"es":"Junto al capitán Granit Xhaka, Rodríguez es el jugador con más internacionalidades en la historia del fútbol suizo. Xhaka también es su mejor amigo en la selección nacional y los dos solían compartir habitación. Juntos ganaron la Copa Mundial Sub-17 en Nigeria en 2009. El éxito histórico lanzó la carrera de Rodríguez, llevándolo al Wolfsburgo, Milán, Eindhoven, Torino y, ahora, Real Betis. Hijo de padre español y madre chilena, creció en el barrio obrero de Schwamendingen en Zurich, pero tuvo problemas en la escuela, por lo que su madre Marcela estaba muy preocupada por él. Marcela, lamentablemente, murió de cáncer en 2016. Sus hermanos Roberto y Francisco también triunfaron como futbolistas profesionales, pero Ricardo es el más exitoso de los tres. Rodríguez tuvo un comienzo difícil en la vida: debido a una hernia diafragmática al nacer, los médicos le dieron sólo un 50 por ciento de posibilidades de sobrevivir. Rodríguez","en":"Alongside the captain, Granit Xhaka, Rodriguez is the player with the most international caps in the history of Swiss football. Xhaka is also his best friend in the national team and the two used to share a room. Together they won the Under-17 World Cup in Nigeria back in 2009. The historic success launched Rodriguez’ career, taking him to Wolfsburg, Milan, Eindhoven, Torino and, now, Real Betis. The son of a Spanish father and a Chilean mother, he grew up in the working-class Zurich neighbourhood of Schwamendingen, but struggled at school, which is why his mother Marcela was very concerned about him. Marcela, sadly, died of cancer in 2016. His brothers Roberto and Francisco also made it as professional footballers, but Ricardo is the most successful of the three. Rodriguez had a difficult start in life: due to a diaphragmatic hernia at birth, doctors gave him only a 50 per cent chance of survival. Rodriguez"} },
  { number: 18, name: 'Eray Cömert', position: 'DF', age: 28, club: 'Valencia', bio: {"es":"Se ganó el cariño de los fieles del Valencia en febrero con algunas animadas celebraciones tras la victoria en el derbi contra el Levante. Después del pitido final, Cömert puso su camiseta en el banderín de córner y celebró eufóricamente ante su propia afición. Imágenes que se volvieron virales. Los aficionados del Levante quedaron menos impresionados y le arrojaron objetos mientras avanzaba por el túnel, con una botella de plástico medio llena golpeando a Cömert en la cabeza. Aunque no se arrepintió. \"No tengo ningún problema con eso\", dijo. \"Las emociones son parte integrante del fútbol, ​​más aún en un derbi\". Llegó al Valencia en 2002 pero no es hasta esta temporada que consigue consolidarse como titular tras dos cesiones (en Nantes y Real Valladolid). Estuvo hasta 2018 jugando como Eray Cümart después de un error de los funcionarios del pasaporte, que afectó a toda la familia, pero tardíamente pudo cambiarlo a la ortografía correcta.","en":"Endeared him to the Valencia faithful in February with some lively celebrations after the derby win against Levante. After the final whistle Cömert put his shirt on the corner flag and celebrated exuberantly in front of his own fans. Images that went viral. Levante fans were less impressed and pelted him with objects as he made his way down the tunnel, with a half-full plastic bottle hitting Cömert on the head. He was unrepentant though. “I’ve no problem with that at all,” he said. “Emotions are part and parcel of football, all the more so in a derby.” Joined Valencia in 2002 but it is not until this season that he managed to establish himself as a starter following two loan spells (at Nantes and Real Valladolid). Was up until 2018 playing as Eray Cümart after a mistake by passport officials - affecting the whole family – but was belatedly able to change it to the correct spelling."} },
  { number: 24, name: 'Aurèle Amenda', position: 'DF', age: 22, club: 'Eintracht Frankfurt', bio: {"es":"A principios de esta temporada, la carrera de Amenda no iba a ninguna parte. En el Eintracht Frankfurt fue principalmente suplente con Dino Toppmöller y se habló de una mudanza invernal, pero el cambio de entrenador a Albert Riera tuvo un efecto transformador para el hombre de Biel. Se ha convertido en un habitual titular en la Bundesliga y el seleccionador nacional, Murat Yakin, ya era fanático del defensor físico. De hecho, lo ve como un futuro sucesor de Manuel Akanji. \"La medida no salió como lo había previsto\", dijo Amenda al Frankfurter Rundschau en marzo. \"Pero me mantuve positivo y mentalmente fuerte, eso me ayudó mucho\". El doble nacional suizo-camerunés pasó por las categorías inferiores del Young Boys, ganando dos títulos de liga y una Copa con el club antes de dar el salto a la Bundesliga a la edad de 21 años.","en":"Earlier this season Amenda’s career was going nowhere. He was mainly a substitute under Dino Toppmöller at Eintracht Frankfurt and there was talk of a winter move but a change of manager, to Albert Riera, had a transformative effect for the man from Biel. He has become a regular starter in the Bundesliga and the national team coach, Murat Yakin, was already a fan of the physical defender. In fact he sees him as a future successor to Manuel Akanji. “The move did not work out the way I had envisaged,” Amenda told Frankfurter Rundschau in March. “But I stayed positive and mentally strong, that helped me a lot.” The Swiss-Cameroonian dual national came through the youth ranks at Young Boys, winning two league titles and one Cup with the club before making the leap to the Bundesliga at the age of 21."} },
  { number: 25, name: 'Luca Jaquez', position: 'DF', age: 23, club: 'Stuttgart', bio: {"es":"\"Al principio no me gustó todo\", dijo Jáquez a blue.ch en 2024 cuando le preguntaron sobre el momento en que la leyenda de Lucerna y entrenador sub-18, Michel Renggli, lo había trasladado de un rol de ataque a un de defensa central. \"Siempre había soñado con una carrera como delantero. Me llevó algunas semanas darme cuenta de que podía tener un futuro en la zaga\". Le da crédito a su madre y a su hermana por convertirse en futbolistas profesionales: \"Mi madre lo es todo para mí. Desde que era joven siempre ha estado a mi lado y me ha apoyado en cada torneo, en cada partido. No sé cómo podría haberme convertido en futbolista sin ella\". ¿Y su hermana, que tuvo que dejar la gimnasia porque el fútbol de Jáquez se hizo cargo y su madre no podía llevarlos a ambos? \"En ese momento estaba tan concentrado en el fútbol que no estoy seguro de haberlo notado. Pero mirando hacia atrás tal vez eso no fue tan justo\". Debía debutar con la selección absoluta en noviembre de 2024, pero Murat Yakin no pudo seleccionar a Jáquez porque había sido expulsado de la sub-21 unas semanas antes. Un habitual en Stuttgart a pesar de la feroz competencia debido a su excelente juego de preparación, es el defensa suizo más talentoso de todas las filas.","en":"“At first I didn’t like it all,” Jaquez told blue.ch in 2024 when asked about the time when the Lucerne legend and Under-18 coach Michel Renggli had moved him from an attacking role to central defence. “I had always dreamed about a career as a forward player. It took me a few weeks before I realised that I could have a future at the back.” Credits his mother and sister for becoming a professional footballer: “My mum is everything for me. Since I was young she has always been by my side and supported me at every tournament, every game. I don’t know how I could have become a footballer without her.” And his sister, who had to stop gymnastics because Jaquez’ football took over and their mum couldn’t drive them to both? “At the time I was so focused on football I am not sure I noticed. But looking back maybe that wasn’t so fair.” Was due to make his debut for the senior national team in November 2024 but Murat Yakin ended up not being able to select Jaquez as he had been sent off for the Under-21s a few weeks earlier. A regular at Stuttgart despite fierce competition because of his superb build-up play, he is the most talented Swiss defender coming through the ranks."} },
  // Volantes
  { number: 6, name: 'Denis Zakaria', position: 'MF', age: 29, club: 'Monaco', bio: {"es":"Borussia Mönchengladbach, Juventus, Chelsea y, ahora, Mónaco. ¿Cómo seguir el ritmo de Denis Zakaria? Casi ningún jugador suizo ha representado a tantos clubes prestigiosos como él, pero con la selección nacional a veces ha sido complicado. El capitán del Mónaco ha tenido problemas para encontrar su lugar con Murat Yakin, principalmente porque no es fácil ser elegido cuando tienes a Granit Xhaka y Remo Freuler en el centro del campo. Y cuando Zakaria fue llamado porque Xhaka estaba ausente, como en los cuartos de final de la Eurocopa 2020 contra España o en septiembre de 2024 contra los mismos oponentes en la Liga de las Naciones, a menudo parecía fuera de lugar en el juego. Ahora, sin embargo, Yakin puede haber encontrado el papel adecuado para Zakaria: como lateral derecho en la defensa de tres, que jugó por primera vez en el amistoso contra Noruega en marzo. \"Fue una actuación exitosa de Denis\", dijo Yakin. Es uno de los líderes de la plantilla de la selección nacional y “hermano mayor” del gran contingente ginebrino de la plantilla. En 2019, en una entrevista con Blick, admitió haber cometido algunos errores cuando era más joven. \"Una vez compré un coche muy caro, pero luego me di cuenta de que había sido un error. No aporta nada. Así que lo vendí\".","en":"Borussia Mönchengladbach, Juventus, Chelsea and, now, Monaco. How to keep up with Denis Zakaria? Hardly any Swiss player has represented as many prestigious clubs as him, yet with the national team it has been complicated at times. The Monaco captain has had trouble finding his place under Murat Yakin, mainly because it is not easy getting picked when you have Granit Xhaka and Remo Freuler in central midfield. And when Zakaria was called upon because Xhaka was missing – such as the Euro 2020 quarter-final against Spain or in September 2024 against the same opponents in the Nations League – he often seemed out of place in the game. Now, however, Yakin may have found the right role for Zakaria: as a right-sided player in a defensive back three, which he played for the first time in the friendly against Norway in March. “It was a successful performance from Denis,” said Yakin. He is one of the leaders in the national team squad set-up and “big brother” of the large Geneva contingent in the squad. In 2019, in an interview with Blick, he admitted to making some mistakes when he was younger. “I bought a really expensive car once but I then realised it was a mistake. It brings nothing. So I sold it.”"} },
  { number: 8, name: 'Remo Freuler', position: 'MF', age: 34, club: 'Bologna', bio: {"es":"Ha recorrido un largo camino desde aquellos días oscuros en los que no logró abrirse camino en la general, a pesar de marcar un gol en el derbi contra el FC Zurich a la edad de 18 años. Primero estuvo cedido en el Winterthur de la Challenge League antes de llamar la atención en Lucerna. En enero de 2016 se unió al Atalanta, donde, a pesar de que muchos le dijeron que su traslado al extranjero llegó demasiado pronto, se convirtió en un éxito instantáneo. Pasó cinco años en Bérgamo, siendo una parte crucial del exitoso paso de Gian Piero Gasperini en el club, adquiriendo experiencia en la Liga de Campeones en el camino. Después de un año con Nottingham Forest en Inglaterra, regresó a Bolonia, donde formó parte del equipo que puso fin a una sequía de trofeos de 50 años al ganar la Coppa Italia. Freuler esta temporada persigue a Stephan Lichtsteiner como el jugador suizo con más partidos en la Serie A y es un líder en las selecciones nacionales. \"Cuando algo no me gusta, no me quedo callado, digo algo\", dijo a watson.ch. \"Si no haces eso, eres un ratoncito gris. Eso es algo que ha cambiado en los últimos años. Pero al final, lo que haces en el campo es siempre lo más importante. Las acciones siempre hablan más que las palabras\".","en":"Has come a long way since those dark days when he failed to make his breakthrough at GC, despite scoring a goal in the derby against FC Zurich at the age of 18. He first went on loan to Challenge League side Winterthur before catching the eye at Lucerne. In January 2016 he joined Atalanta, where, despite many telling him the move abroad came too early, became an instant hit. He spent five years in Bergamo, being a crucial part of Gian Piero Gasperini’s successful time at the club, gaining Champions League experience along the way. After a year with Nottingham Forest in England he returned to Bologna, where he was part of the side who ended a 50-year trophy drought by winning the Coppa Italia. Freuler is this season chasing down Stephan Lichtsteiner as the Swiss player with most Serie A appearances and is a leader within the national team set-ups. “When I don’t like something, I don’t stay quiet, I say something,” he told watson.ch. “If you don’t do that you are a little grey mouse. That is something that has changed in recent years. But at the end what you do on the pitch is always the most important thing. Actions always speak louder than words.”"}, special: "Running machine" },
  { number: 10, name: 'Granit Xhaka', position: 'MF', age: 33, club: 'Sunderland', captain: true, bio: {"es":"Capitán, récord y mano derecha del entrenador: Granit Xhaka es el líder indiscutible de la selección nacional en su séptimo gran torneo, tanto dentro como fuera del campo. En los amistosos de marzo contra Alemania y Noruega, el capitán descansó tres cuartos de los dos partidos. “Tenemos que estar preparados para jugar sin él en ocasiones, o cuando esté marcado hombre a hombre, como sucedió contra Alemania”, dijo Murat Yakin. Después de un comienzo difícil en su relación, la pareja ahora es muy unida. El centrocampista ya lleva un tiempo en el mercado. En 2011, Ottmar Hitzfeld lanzó a Xhaka, entonces de 18 años, al fondo de Wembley durante un partido de clasificación para la Eurocopa contra Inglaterra y el ganador del Mundial Sub-17 es ahora el poseedor del récord de partidos internacionales en su país con más de 140 apariciones. Muchos sintieron que su carrera estaba decayendo cuando se unió al Bayer Leverkusen en 2023 después de siete años en el Arsenal, pero fue todo lo contrario: y como líder de Xabi Alonso en el campo llevó al club a ganar su primer título de la Bundesliga, ganó la Copa y llegó a la final de la Europa League. Ahora, de regreso en Inglaterra, dice: “Para mí también es importante vivir momentos de sufrimiento y solidaridad”. Sus padres son de Kosovo; su padre, Ragip, fue detenido en 1986, cuando tenía 22 años, durante una manifestación contra el gobierno central comunista.","en":"Captain, record-breaker and the manager’s right-hand man: Granit Xhaka is the undisputed leader of the national team at his seventh major tournament – both on and off the pitch. In the March friendlies against Germany and Norway, the captain was rested for three quarters of the two matches. “We have to be prepared to play without him at times, or when he is marked man-to-man, as he was against Germany,” said Murat Yakin. After a difficult start to their relationship, the pair are now very close. The midfielder has been around for some time now. In 2011, Ottmar Hitzfeld threw the then 18-year-old Xhaka in at the deep end at Wembley during a Euro qualifier against England and the Under-17 World Cup winner is now the record holder for international caps in his country with more than 140 appearances. Many felt that his career was on the way down when he joined Bayer Leverkusen in 2023 after seven years at Arsenal but it was the opposite - and as Xabi Alonso’s leader on the pitch he took the club to a first ever Bundesliga title, won the Cup and reached the Europa League final. Now back in England, he says: “It’s important for me to experience moments of suffering and solidarity too.” His parents are from Kosovo; his father, Ragip, was arrested in 1986 at the age of 22 during a demonstration against the communist central government"}, special: "Captain" },
  { number: 14, name: 'Ardon Jashari', position: 'MF', age: 23, club: 'Milan', bio: {"es":"Un gran punto de discusión en la selección nacional. Jashari es considerado el centrocampista más talentoso de Suiza y un posible sucesor de Granit Xhaka, pero el tiempo de juego hasta ahora ha sido limitado con el jugador del Sunderland y Remo Freuler a menudo prefería al jugador de 24 años. Ha mejorado enormemente desde que se unió al Club Brujas en 2024 y ahora está en el Milán. En 2025 le contó a Sky sus primeros años en Suiza. \"Crecí en Neuheim junto a familias suizas que tenían un nivel social más alto, así como albanesas, que vivían más modestamente. El sentimiento de esta diferencia a veces era doloroso porque tenía la sensación de que tenía que admirar a las personas más ricas, como si yo valiera menos. Pero mis padres hicieron todo lo posible para minimizar esta diferencia y asegurarse de que yo no me viera afectado por esta desigualdad social. Trabajaron muy duro para asegurarse de que tuviéramos las mismas oportunidades que los demás\".","en":"A big discussion point in the national team. Jashari is regarded as the most talented midfielder in Switzerland and a possible successor to Granit Xhaka but game time has so far been limited with the Sunderland player and Remo Freuler often preferred to the 24-year-old. Has improved immeasurably since joining Club Brugge in 2024 and is now with Milan. In 2025 he told Sky about his early years in Switzerland. “I grew up in Neuheim next to Swiss families who had a higher social standard as well as Albanian ones, who lived more modestly. The feeling of this difference was painful at times as I had the feeling that I had to look up to the wealthier people, as if I were worth less. But my parents did everything to minimise this difference and to make sure that I was not affected by this social inequality. They worked extremely hard to make sure that we had the same opportunities as the others.”"} },
  { number: 15, name: 'Djibril Sow', position: 'MF', age: 29, club: 'Sevilla', bio: {"es":"El centrocampista llega al Mundial con mucha alegría tras una de las mejores temporadas de su carrera. Especialmente de cara a la portería ha demostrado un nuevo y mejorado nivel de madurez. Para la selección nacional, sin embargo, la historia es diferente, ya que, a pesar de disputar más de 50 partidos internacionales, no tiene un papel claro con Murat Yakin. Fue titular en el último Mundial, pero no ha sido convocado en los últimos 12 meses, en parte por una lesión en un dedo del pie. “Djibbi” puede jugar como número 6 y como número 8 y sabe cómo ganar títulos. En 2018 formó parte del equipo YB que ganó la liga por primera vez en 32 años. Y en 2022 consiguió la Europa League con el Eintracht Frankfurt.","en":"The midfielder is arriving at the World Cup with a spring in his step after one of the best seasons of his career. Especially in front of goal he has displayed a new, improved level of maturity. For the national team, however, it is a different story as, despite winning more than 50 caps, he does not have a clear role under Murat Yakin. He was a starterF at the last World Cup but has not been called upon in the past 12 months, partly because of a toe injury. “Djibbi” can play as a No 6 and a No 8 - and he knows how to win titles. In 2018, he was part of the YB side that won the league for the first time in 32 years. And in 2022, he secured the Europa League with Eintracht Frankfurt."} },
  { number: 16, name: 'Christian Fassnacht', position: 'MF', age: 32, club: 'Young Boys', bio: {"es":"La mayor sorpresa en la plantilla de Murat Yakin. El otoño pasado, Fassnacht regresó a la selección nacional después de una ausencia de dos años y medio, pero en marzo volvió a faltar al equipo. Con 18 goles, fue el máximo goleador de la Superliga suiza en 2025-26 y es un auténtico jugador de equipo. \"Las estadísticas no mienten; él sabe dónde está el objetivo\", afirmó Yakin. El mejor momento de Fassnacht llegó en los octavos de final de la Eurocopa 2020, cuando ganó la posesión de los dos goles tardíos de Suiza en el empate 3-3 con Francia antes de la victoria en los penaltis. El delantero fue expulsado de la selección juvenil de Zúrich, lo que le obligó a pasar varios años en el fútbol amateur antes de dar el salto a la máxima categoría pasando por Winterthur, Thun y luego Young Boys. Desde entonces se ha convertido en una leyenda en Berna. Su paso por el extranjero en Norwich no fue un éxito, por lo que regresó en 2025 después de un año y medio.","en":"The biggest surprise in Murat Yakin’s squad. Last autumn, Fassnacht returned to the national setup after a two-and-a-half-year absence but was again missing from the squad this March. With 18 goals, he was the top scorer in the Swiss Super League in 2025-26 and he is a true team player. “The statistics don’t lie; he knows where the goal is,” said Yakin. Fassnacht’s finest hour came in the Euro 2020 Last 16, when he won possession for both Switzerland’s late goals in a 3-3 draw with France before victory on penalties. The striker was once dropped from the Zurich youth team, forcing him to spend several years in amateur football before making the leap to the top flight via Winterthur, Thun and then Young Boys. In Bern, he has since become a legend. His spell abroad at Norwich was not a success, so he returned in 2025 after a year and a half."}, special: "Surprise call-up" },
  { number: 20, name: 'Michel Aebischer', position: 'MF', age: 29, club: 'Pisa', bio: {"es":"Un hombre para el gran momento. Después de ser principalmente suplente de Suiza, aprovechó su oportunidad en la Eurocopa 2024 y realizó su mejor actuación hasta el momento con su país en el partido inaugural contra Hungría, anotando un gol y dando una asistencia. Lo que no se sabía en ese momento era que estaba jugando con dolor debido a una lesión en la ingle. Al final tuvo que ser operado y perdió su plaza en el Bolonia y en la selección. Por tanto, en el verano de 2025 se incorporó a Pisa. “Ya no tenía el papel que quería”, dijo. \"Porque soy alguien a quien le gusta tener mucho tiempo de juego y también desempeña un papel importante en el equipo. Por eso di un paso atrás deliberadamente\". Habla con fluidez los tres idiomas oficiales suizos: italiano, alemán y francés, y respondió diplomáticamente cuando se le preguntó si prefería la comida italiana o suiza: \"No te costará encontrar buena comida en Italia, eso es seguro\", antes de añadir que le faltaba una buena fondue.","en":"A man for the big moment. After being mainly a substitute for Switzerland he grabbed his chance at Euro 2024 and produced his best performance yet for his country in the opening game against Hungary, scoring a goal and providing an assist. What wasn’t known at the time was that he was playing through the pain because of a groin injury. In the end he had to have an operation and lost his place at Bologna and the national team. In the summer of 2025 he therefore joined Pisa. “I no longer had the role I wanted,” he said. “Because I’m someone who likes to get plenty of playing time and also plays an important role in the team. That’s why I deliberately took a step back.” Fluent in all three official Swiss languages – Italian, German and French, he responded diplomatically when asked if he preferred Italian or Swiss food: “You are not going to struggle to find nice food in Italy, that’s for sure” before adding that he was missing a good fondue."}, special: "Linguist" },
  { number: 22, name: 'Fabian Rieder', position: 'MF', age: 24, club: 'Augsburg', bio: {"es":"“Hay que asumir más responsabilidades”, dijo Rieder en 2023 en una entrevista con la televisión suiza cuando se le preguntó sobre la muerte de su padre cuando el jugador tenía sólo 11 años. \"Te enfrentas a cosas que no esperabas. Pero también tengo que dejar claro que tuve una buena infancia. Sin embargo, eso significó que probablemente era un poco más maduro que otros, en cuanto a personalidad. El entrenador de la selección nacional, Murat Yakin, es un gran admirador del trabajador incansable que a menudo dirige la prensa de los suizos. En 2023, dejó a los campeones suizos Young Boys por Francia y Rennes en un acuerdo valorado en £14,2 millones. Allí no le funcionó. sin embargo, y después de una cesión igualmente azarosa en el Stuttgart, fichó por el Augsburgo en el verano de 2025.","en":"“You have to take more responsibility,” Rieder said in 2023 in an Interview with Swiss Television when asked about his father dying when the player was only 11 years old. “You are confronted by things you didn’t expect. But I also have to make clear that I had a good childhood. It did mean, though, that I was probably a bit more mature than others, personality wise. The national team coach, Murat Yakin, is a big fan of the tireless worker who often leads the press for the Swiss. In 2023, he left Swiss serial champions Young Boys for France and Rennes in a deal worth £14.2m. It didn’t work out for him there, however, and after an equally hit-and-miss spell on loan at Stuttgart, he joined Augsburg in the summer of 2025."} },
  // Delanteros
  { number: 7, name: 'Breel Embolo', position: 'FW', age: 29, club: 'Rennes', bio: {"es":"Breel Embolo ha experimentado una transformación asombrosa en los últimos años. El delantero, que siempre había destacado por su impresionante físico, ahora ha sumado más goles a su repertorio. En el momento de escribir este artículo, ha marcado ocho goles con Suiza desde principios de 2025, la misma cantidad de goles que había marcado en los seis años anteriores con su país. Pero no es sólo sobre el terreno de juego donde ha madurado el delantero, nacido en Camerún pero criado en Suiza. En el pasado, Embolo ha tendido a causar controversia. A principios de 2021, asistió a una fiesta ilegal a pesar del confinamiento por el Covid y se escondió en una bañera cuando llegó la policía. En 2023, fue declarado culpable de realizar múltiples amenazas. Su regreso al Mónaco se vio frustrado porque supuestamente obtuvo dos certificados Covid falsos en 2021. Sin embargo, hoy en día, el jugador de Basilea es un líder clave dentro del equipo, parte del equipo de capitanía y, gracias a su bilingüismo, un vínculo importante entre los jugadores de habla alemana y francesa.","en":"Breel Embolo has undergone an astonishing transformation in recent years. The forward, who had always stood out for his impressive physicality, has now added more goals to his repertoire. At the time of writing he has scored eight times for Switzerland since the start of 2025 – the same amount of goals he had in the previous six years for his country. But it is not only on the pitch that the striker, born in Cameroon but raised in Switzerland, has matured. In the past, Embolo has had a tendency to cause controversy. In early 2021, he attended an illegal party despite the Covid lockdown and hid in a bathtub when the police arrived. In 2023, he was convicted of making multiple threats. His comeback at Monaco was derailed because he allegedly obtained two fake Covid certificates in 2021. Today, however, the man from Basel is a key leader within the team, part of the captaincy team and, thanks to his bilingualism, an important link between the German- and French-speaking players."}, special: "Main goalscorer" },
  { number: 9, name: 'Johan Manzambi', position: 'FW', age: 20, club: 'Freiburg', bio: {"es":"El gran descubrimiento de los últimos 12 meses. Murat Yakin, que apareció aparentemente de la nada en Friburgo, lo convocó para los amistosos de verano de 2025, y Manzambi respondió anotando y asistiendo en su primera apertura, una victoria por 4-0 contra Estados Unidos. Este jugador técnicamente dotado puede jugar en cualquier posición y en Friburgo suele jugar como centrocampista defensivo o ofensivo, mientras que a menudo ha aparecido en la banda de su país. Ha madurado desde que se mudó de la parte francófona de Suiza a Alemania a la edad de 17 años, pero aún puede perder la calma en el campo y fue expulsado en dos partidos consecutivos de la Bundesliga durante la temporada 2025-26. Después de que el Friburgo venciera al Basilea por 2-1 en la Europa League la temporada pasada, Xherdan Shaqiri irrumpió en una entrevista con Manzambi y dijo: \"Para él fue bueno jugar, tiene un gran futuro por delante\".","en":"The big discovery of the past 12 months. Having burst on to the scene from seemingly nowhere at Freiburg Murat Yakin called him up to the summer friendlies in 2025 - and Manzambi responded by scoring and assisting on his first start, a 4-0 win against USA. The technically gifted player can play in any position and at Freiburg he is often deployed as a defensive or attacking midfielder while he has often appeared on the wing for his country. Has matured since moving from the French-speaking part of Switzerland to Germany at the age of 17 but can still lose his cool on the pitch, and was sent off in two consecutive Bundesliga matches during the 2025-26 season. After Freiburg had beaten Basel 2-1 in the Europa League last season Xherdan Shaqiri gatecrashed an interview with Manzambi and said: “It was good to him play, he has a big future ahead of him.”"}, special: "On the rise" },
  { number: 11, name: 'Dan Ndoye', position: 'FW', age: 25, club: 'Nottingham Forest', bio: {"es":"Tuvo su gran avance en la Eurocopa 2024 y, después de la victoria por 3-1 contra Hungría, él y su padre, Saliou, hablaron por FaceTime con la abuela de Dan, Bineta, que vive en Senegal y anima a su nieto desde allí. \"Sigo recibiendo fotos de Senegal. La gente de allí sigue regularmente los partidos de la selección suiza\", dice Ndoye, que suele viajar de vacaciones a la costa occidental de África. La familia juega un papel muy importante en la vida de este nativo de Lausana, que tiene un hermano menor y una hermana menor. El verano pasado se convirtió en el segundo jugador suizo más caro de la historia detrás de Granit Xhaka, ya que Nottingham Forest pagó alrededor de £ 35 millones para ficharlo procedente del Bolonia. Ha sido una primera temporada intermitente para el extremo en Inglaterra, pero es un titular garantizado para Suiza gracias a su velocidad y capacidad de regate. \"Soy muy ambicioso y sé lo que puedo hacer\", dijo en octubre. \"Soy alguien que trabaja duro y quiere desarrollarse, por eso estoy hoy en la Premier League. Eso no significa que esté feliz, aunque siempre querré llegar más alto\".","en":"Had his breakthrough at Euro 2024 and, after the 3-1 victory against Hungary, he and his father, Saliou, FaceTimed with Dan’s grandmother Bineta, who lives in Senegal and is cheering on her grandson from there. “I keep getting photos from Senegal. People there follow the Swiss national team’s matches regularly,” says Ndoye, who often goes on holiday to the west coast of Africa. Family plays a very important role in the life of the Lausanne native, who has a younger brother and a younger sister. Last summer he became the second most expensive Swiss player ever behind Granit Xhaka as Nottingham Forest paid around £35m to sign him from Bologna. It has been a stop-start first season for the winger in England but he is a guaranteed starter for Switzerland thanks to his speed and dribbling ability. “I am very ambitious and know what I can do,” he said in October. “I am someone who works hard and wants to develop – that is why I am in the Premier League today. That doesn’t mean that I am happy, though, I will always want to go higher.”"} },
  { number: 17, name: 'Ruben Vargas', position: 'FW', age: 28, club: 'Sevilla', bio: {"es":"A principios de 2025, después de cinco años y medio en Augsburgo, Vargas pasó a La Liga y al Sevilla. Allí, el nativo de Lucerna ha sido titular habitual cuando está en forma, y ​​lo mismo ocurre con Suiza. Es conocido como el jugador favorito no oficial del entrenador de la selección nacional, Murat Yakin. Uno de los héroes de Suiza contra Italia en el partido de octavos de final contra Italia en la Eurocopa 2024, anotando el segundo gol de una victoria por 2-0 con un impresionante disparo de larga distancia. Hijo de padre dominicano y madre suiza, completó un aprendizaje de tres años como pintor durante su estancia en el FC Lucerna. Su padre es instructor de golf y a menudo también se puede ver a Vargas en el campo. En la selección nacional tiene una amistad especialmente estrecha con Noah Okafor.","en":"In early 2025, after five and a half years at Augsburg, Vargas moved to La Liga and Sevilla. There, the Lucerne native has been a regular starter when fit and the same goes for Switzerland. He is known as the unofficial favourite player of national team coach, Murat Yakin. One of Switzerland’s heroes against Italy in the Last 16-game against Italy at Euro 2024, scoring the second goal of a 2-0 victory with a stunning long-range strike. The son of a Dominican father and a Swiss mother, he completed a three-year apprenticeship as a painter during his time at FC Lucerne. His father is a golf instructor and Vargas can often be seen on the course as well. In the national team, he has a particularly close friendship with Noah Okafor."} },
  { number: 19, name: 'Noah Okafor', position: 'FW', age: 26, club: 'Leeds', bio: {"es":"A principios de año parecía impensable que Okafor viajara al Mundial. Las cosas iban mal desde la Eurocopa 2024, donde no jugó ni un solo minuto, pero se dice que mostró falta de espíritu de equipo y estuvo de mal humor. Luego se reunió con el director de la selección nacional, Pierluigi Tami, sin decírselo al entrenador, Murat Yakin. Finalmente, tras quedar fuera de la convocatoria para las eliminatorias mundialistas, criticó a Yakin en una entrevista. Sin embargo, sorprendentemente, una visita de Yakin a Leeds parece haber resuelto el problema y Okafor fue incluido para los amistosos de marzo. Allí pidió disculpas al equipo, lo que es una buena noticia para Suiza porque tiene cualidades que ningún otro delantero suizo tiene en este momento.","en":"At the start of the year it seemed unthinkable that Okafor would travel to the World Cup. Things had been bad since the Euro 2024 where he did not play a single minute but is said to have displayed a lack of team spirit and been bad-tempered. He then proceeded to meet the national team director Pierluigi Tami without telling the coach, Murat Yakin. Finally, after being left out of the squad for the World Cup qualifiers, he criticised Yakin in an interview. Remarkably, though, a visit by Yakin to Leeds seems to have solved the issue and Okafor was included for the March friendlies. There he apologised to the team, which is good news for Switzerland because he has qualities that no other Swiss striker has at the moment."} },
  { number: 23, name: 'Zeki Amdouni', position: 'FW', age: 26, club: 'Burnley', bio: {"es":"El hijo del propietario de un quiosco turco y de una madre tunecina todavía es considerado uno de los mayores talentos del país, pero se ha enfrentado a una carrera contrarreloj para recuperarse de una lesión del ligamento cruzado anterior que sufrió en la pretemporada con el Burnley. Vincent Kompany, del Bayern de Múnich, es un admirador y fue el belga quien llevó a Amdouni a Inglaterra en 2023. El técnico suizo, Murat Yakin, también tiene en alta estima a un jugador cuyo estilo es el de un futbolista callejero de Ginebra, no muy diferente al de Xherdan Shaqiri. Yakin lo invitó a formar parte del equipo para los amistosos de marzo a pesar de que aún no estaba en forma. En una entrevista con Blick explicó por qué ahora prefiere a Messi a Ronaldo. \"Cuando era joven me gustaba todo de Ronaldo: su pelo, sus botas, todo su estilo. Sin embargo, cuando cumplí 13 años y realmente comencé a entender el fútbol, ​​solo había un jugador para mí: Messi\". También explicó por qué ha adoptado una celebración de gol con arco y flecha: “Fue algo entre un amigo y yo”, dijo. \"Viene de un rapero francés llamado Jul, que canta sobre una flecha en una de sus canciones, así que le dije a mi amigo que de ahí en adelante iba a hacer eso como celebración. Quería hacer algo que nadie más hiciera\".","en":"The son of a Turkish kiosk owner and a Tunisian mother is still regarded as one of the country’s greatest talents, but he has faced a race against time to recover from an ACL injury suffered in pre-season with Burnley. Bayern Munich’s Vincent Kompany is an admirer and it was the Belgian who took Amdouni to England in 2023. The Switzerland manager, Murat Yakin, also thinks highly of a player whose style is that of a street footballer from Geneva, not dissimilar to that of Xherdan Shaqiri. Yakin invited him to be part of the squad for the March friendlies despite not being match-fit yet. In an interview with Blick he explained why he now prefers Messi to Ronaldo. “When I was young I liked everything about Ronaldo; his hair, his boots, his whole style. When I turned 13, though, and really started to understand football there was only one player for me: Messi.” He also explained why he has adopted a bow and arrow goal celebration: “It was something between me and a friend,” he said. “It comes from a French rapper called Jul he sings about an arrow in one of his songs so I said to the friend that from then on I was going to do that as a celebration. I wanted to do something no one else does.”"}, special: "Messi-admirer" },
  { number: 26, name: 'Cedric Itten', position: 'FW', age: 0, club: 'Fortuna Düsseldorf', bio: {"es":"\"Lo más importante es la pasión y la alegría de jugar al fútbol\", dijo Itten cuando se le preguntó cómo había llegado a ser futbolista profesional. \"Por supuesto que hay que tener algo de talento pero, sobre todo, trabajo duro. El objetivo tiene que ser mejorar cada día, esa fue la clave de mi éxito\". Durante la temporada 2025-26 ha sido el delantero suizo más prolífico en el extranjero, aunque juega en su contra el hecho de haber jugado en la segunda división alemana en el Fortuna Düsseldorf. El ex jugador del Rangers (ganó el título en Escocia) no formó parte del equipo para los amistosos de marzo, pero trabajó duro para ser incluido en el grupo de viaje al Mundial. Marcó a los seis minutos de su debut internacional y tiene, en el momento de escribir este artículo, un buen récord de cinco goles en 13 partidos con Suiza. Este será su primer gran torneo para su país.","en":"“The most important thing is the passion and joy of playing football,” Itten said when asked how he has made it as a professional footballer. “Of course you have to have some talent but, above all, hard work. The goal has to be to improve every single day, that was the key to my success.” During the 2025-26 season he has been the most prolific Swiss striker abroad, although the fact that he has been playing in the second tier in Germany for Fortuna Düsseldorf counts against him. The former Rangers players - he won the title in Scotland - was not part of the squad for the March friendlies but worked hard to get included in the travelling party to the World Cup. He scored six minutes into his international debut and has, at the time of writing, a good record of five goals in 13 games for Switzerland. This will be his first major tournament for his country."} },
];

export const lineup = {
  formation: '4-3-3',
  startingXI: [1, 13, 4, 5, 3, 8, 10, 22, 17, 7, 11]
};
